// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetAccountLimits Current provider limits by configured account
	// (GET /api/v1/accounts/limits)
	GetAccountLimits(ctx context.Context, request GetAccountLimitsRequestObject) (GetAccountLimitsResponseObject, error)
	// GetAnalyticsOverview Dashboard analytics snapshot
	// (GET /api/v1/analytics/overview)
	GetAnalyticsOverview(ctx context.Context, request GetAnalyticsOverviewRequestObject) (GetAnalyticsOverviewResponseObject, error)
	// AuthSession Read browser authentication state
	// (GET /api/v1/auth/session)
	AuthSession(ctx context.Context, request AuthSessionRequestObject) (AuthSessionResponseObject, error)
	// ListAllRuns List All Runs
	// (GET /api/v1/runs)
	ListAllRuns(ctx context.Context, request ListAllRunsRequestObject) (ListAllRunsResponseObject, error)
	// ListSessions List Sessions
	// (GET /api/v1/sessions)
	ListSessions(ctx context.Context, request ListSessionsRequestObject) (ListSessionsResponseObject, error)
	// CreateSession Create Session
	// (POST /api/v1/sessions)
	CreateSession(ctx context.Context, request CreateSessionRequestObject) (CreateSessionResponseObject, error)
	// GetSession Read Session
	// (GET /api/v1/sessions/{sid})
	GetSession(ctx context.Context, request GetSessionRequestObject) (GetSessionResponseObject, error)
	// GetEvents Events
	// (GET /api/v1/sessions/{sid}/events)
	GetEvents(ctx context.Context, request GetEventsRequestObject) (GetEventsResponseObject, error)
	// StreamEvents Stream Events
	// (GET /api/v1/sessions/{sid}/events/stream)
	StreamEvents(ctx context.Context, request StreamEventsRequestObject) (StreamEventsResponseObject, error)
	// GetHistory History
	// (GET /api/v1/sessions/{sid}/history)
	GetHistory(ctx context.Context, request GetHistoryRequestObject) (GetHistoryResponseObject, error)
	// ListRuns List Runs
	// (GET /api/v1/sessions/{sid}/runs)
	ListRuns(ctx context.Context, request ListRunsRequestObject) (ListRunsResponseObject, error)
	// CreateRun Create Run
	// (POST /api/v1/sessions/{sid}/runs)
	CreateRun(ctx context.Context, request CreateRunRequestObject) (CreateRunResponseObject, error)
	// GetRun Read Run
	// (GET /api/v1/sessions/{sid}/runs/{rid})
	GetRun(ctx context.Context, request GetRunRequestObject) (GetRunResponseObject, error)
	// CancelRun Cancel Run
	// (POST /api/v1/sessions/{sid}/runs/{rid}/cancel)
	CancelRun(ctx context.Context, request CancelRunRequestObject) (CancelRunResponseObject, error)
	// SendMessage Send Message
	// (POST /api/v1/sessions/{sid}/runs/{rid}/messages)
	SendMessage(ctx context.Context, request SendMessageRequestObject) (SendMessageResponseObject, error)
	// BrowserCallback Consume a signed SAML HTTP-POST response
	// (POST /auth/callback)
	BrowserCallback(ctx context.Context, request BrowserCallbackRequestObject) (BrowserCallbackResponseObject, error)
	// BrowserLogin Start SP-initiated SAML login
	// (GET /auth/login)
	BrowserLogin(ctx context.Context, request BrowserLoginRequestObject) (BrowserLoginResponseObject, error)
	// BrowserLogout Revoke the local browser session
	// (POST /auth/logout)
	BrowserLogout(ctx context.Context, request BrowserLogoutRequestObject) (BrowserLogoutResponseObject, error)
	// Health Health
	// (GET /health)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
	// Ready Ready
	// (GET /ready)
	Ready(ctx context.Context, request ReadyRequestObject) (ReadyResponseObject, error)
	// SamlMetadata Read service provider metadata
	// (GET /saml/metadata)
	SamlMetadata(ctx context.Context, request SamlMetadataRequestObject) (SamlMetadataResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

